\begin{tabular}{lcccc}
\toprule
Benchmark & $J$ & $\gamma$ [95\% CI] & PPP & cal MAE \\
\midrule
MMLU & 18 & +0.35 [$-$0.60, 1.41] & 0.62 & 0.008 \\
